@Test
void multiProvider() throws IOException, GeneralSecurityException {
    String[][] values = { { getClass().getSimpleName(), getCurrentTestName() }, { new Date(System.currentTimeMillis()).toString() }, { getClass().getPackage().getName() } };
    List<String> expected = new ArrayList<>();
    Collection<PasswordIdentityProvider> providers = new LinkedList<>();
    for (String[] va : values) {
        Collection<String> passwords = Arrays.asList(va);
        expected.addAll(passwords);
        PasswordIdentityProvider p = PasswordIdentityProvider.wrapPasswords(passwords);
        assertProviderContents("Wrapped", p, passwords);
        providers.add(p);
    }
    PasswordIdentityProvider p = PasswordIdentityProvider.multiProvider(null, providers);
    assertProviderContents("Multi", p, expected);
}

@Test
void identityFilePaths() throws IOException {
    final String config = //
    "IdentityFile ~/.ssh/%r.key0\n" + //
    "Host foo\n" + //
    "IdentityFile ~/.ssh/%r.key1\n" + //
    "IdentityFile ~/.ssh/%r.key2\n" + //
    "Host *\n" + "IdentityFile ~/.ssh/%r.key3";
    try (InputStream in = new ByteArrayInputStream(config.getBytes(StandardCharsets.US_ASCII))) {
        List<HostConfigEntry> entries = HostConfigEntry.readHostConfigEntries(in, true);
        HostConfigEntryResolver resolver = HostConfigEntry.toHostConfigEntryResolver(entries);
        HostConfigEntry resolved = resolver.resolveEffectiveHost("foo", -1, null, "testuser", null, null);
        assertEquals("foo", resolved.getHostName());
        assertEquals(22, resolved.getPort());
        assertEquals("testuser", resolved.getUsername());
        String prop = resolved.getProperty(HostConfigEntry.IDENTITY_FILE_CONFIG_PROP);
        assertNotNull(prop);
        assertFalse(prop.contains("~"));
        String[] split = prop.split(",");
        assertEquals(4, split.length);
        Collection<String> identities = resolved.getIdentities();
        assertEquals(4, identities.size());
        int i = 0;
        for (String id : identities) {
            assertFalse(id.contains("~"));
            assertTrue(id.endsWith("testuser.key" + i));
            assertEquals(split[i], id);
            i++;
        }
    }
}

@Test
void configFileReload() throws IOException {
    Path dir = getTempTargetRelativeFile(getClass().getSimpleName());
    AtomicInteger reloadCount = new AtomicInteger();
    ConfigFileHostEntryResolver resolver = new ConfigFileHostEntryResolver(assertHierarchyTargetFolderExists(dir).resolve(getCurrentTestName() + ".config.txt")) {

        @Override
        protected List<HostConfigEntry> reloadHostConfigEntries(Path path, String host, int port, String username, String proxyJump) throws IOException {
            reloadCount.incrementAndGet();
            return super.reloadHostConfigEntries(path, host, port, username, proxyJump);
        }
    };
    Path path = resolver.getPath();
    HostConfigEntry expected = new HostConfigEntry(getCurrentTestName(), getCurrentTestName(), 7365, getCurrentTestName());
    testConfigFileReload("Non-existing", path, reloadCount, null, resolver, expected, null);
    testConfigFileReload("Empty", path, reloadCount, Collections.emptyList(), resolver, expected, null);
    testConfigFileReload("Global", path, reloadCount, Collections.singletonList(new HostConfigEntry(HostPatternsHolder.ALL_HOSTS_PATTERN, expected.getHost(), expected.getPort(), expected.getUsername())), resolver, expected, expected);
    testConfigFileReload("Wildcard", path, reloadCount, Arrays.asList(new HostConfigEntry(expected.getHost() + Character.toString(HostPatternsHolder.WILDCARD_PATTERN), expected.getHost(), expected.getPort(), expected.getUsername()), new HostConfigEntry(HostPatternsHolder.ALL_HOSTS_PATTERN, getClass().getSimpleName(), 1234, getClass().getSimpleName())), resolver, expected, expected);
    testConfigFileReload("Specific", path, reloadCount, Arrays.asList(new HostConfigEntry(getClass().getSimpleName() + Character.toString(HostPatternsHolder.WILDCARD_PATTERN), getClass().getSimpleName(), 1234, getClass().getSimpleName()), expected, new HostConfigEntry(HostPatternsHolder.ALL_HOSTS_PATTERN, getClass().getSimpleName(), 1234, getClass().getSimpleName())), resolver, expected, expected);
}

