// see SSHD-606
@Test
void validateStrictKeyFilePermissions() throws IOException {
    Assumptions.assumeTrue(!OsUtils.isWin32(), "Test does not always work on Windows");
    Path file = getTempTargetRelativeFile(getClass().getSimpleName(), getCurrentTestName());
    outputDebugMessage("%s deletion result=%s", file, Files.deleteIfExists(file));
    assertNull(KeyUtils.validateStrictKeyFilePermissions(file), "Unexpected violation for non-existent file: " + file);
    assertHierarchyTargetFolderExists(file.getParent());
    try (OutputStream output = Files.newOutputStream(file)) {
        output.write((getClass().getName() + "#" + getCurrentTestName() + "@" + new Date(System.currentTimeMillis())).getBytes(StandardCharsets.UTF_8));
    }
    Collection<PosixFilePermission> perms = IoUtils.getPermissions(file);
    if (GenericUtils.isEmpty(perms)) {
        assertNull(KeyUtils.validateStrictKeyFilePermissions(file), "Unexpected violation for no permissions file: " + file);
    } else if (OsUtils.isUNIX()) {
        Map.Entry<String, Object> violation = null;
        for (PosixFilePermission p : KeyUtils.STRICTLY_PROHIBITED_FILE_PERMISSION) {
            if (perms.contains(p)) {
                violation = KeyUtils.validateStrictKeyFilePermissions(file);
                assertNotNull(violation, "Unexpected success for permission=" + p + " of file " + file + " permissions=" + perms);
                break;
            }
        }
        if (violation == null) {
            // we expect a failure since the parent does not have the necessary permissions
            assertNotNull(KeyUtils.validateStrictKeyFilePermissions(file), "Unexpected UNIX success for file " + file + " permissions=" + perms);
        }
    } else {
        assertNull(KeyUtils.validateStrictKeyFilePermissions(file), "Unexpected Windows violation for file " + file + " permissions=" + perms);
    }
}

