@ParameterizedTest(name = "{0}")
public void signCertificate(TestParams params) throws Exception {
    initGenerateOpenSSHClientCertificateTest(params);
    final PublicKey clientPublicKey = readPublicKeyFromResource(getClientPublicKeyResource());
    final String caName = getCAPrivateKeyResource();
    final FileKeyPairProvider keyPairProvider = CommonTestSupportUtils.createTestKeyPairProvider(caName);
    final KeyPair caKeypair = keyPairProvider.loadKeys(null).iterator().next();
    String signatureAlgorithm = null;
    int i = caName.indexOf("rsa2_");
    if (i > 0) {
        signatureAlgorithm = "rsa-sha2-" + caName.substring(i + 5);
    }
    final OpenSshCertificate signedCert = OpenSshCertificateBuilder.userCertificate().serial(0L).publicKey(clientPublicKey).id("user01").principals(Collections.singletonList("user01")).criticalOptions(Arrays.asList(new OpenSshCertificate.CertificateOption("force-command", "/path/to/script.sh"), new OpenSshCertificate.CertificateOption("source-address", "127.0.0.1/32"), new OpenSshCertificate.CertificateOption("verify-required"))).extensions(Arrays.asList(new OpenSshCertificate.CertificateOption("no-touch-required"), new OpenSshCertificate.CertificateOption("permit-X11-forwarding"), new OpenSshCertificate.CertificateOption("permit-agent-forwarding"), new OpenSshCertificate.CertificateOption("permit-port-forwarding"), new OpenSshCertificate.CertificateOption("permit-pty"), new OpenSshCertificate.CertificateOption("permit-user-rc"))).sign(caKeypair, signatureAlgorithm);
    // encode to ssh public key format
    final OpenSSHKeyPairResourceWriter writer = new OpenSSHKeyPairResourceWriter();
    final ByteArrayOutputStream baos = new ByteArrayOutputStream();
    writer.writePublicKey(signedCert, "user01", baos);
    final String encodedCertData = new String(baos.toByteArray(), StandardCharsets.UTF_8);
    // now, decode and check for equality
    final OpenSshCertificate decodedCert = readOpenSshCertificate(encodedCertData);
    // Check that they both validate
    verifySignature(signedCert, signatureAlgorithm);
    verifySignature(decodedCert, signatureAlgorithm);
    assertCertsEqual(signedCert, decodedCert);
}

