            public boolean isInteractionAllowed(ClientSession session) {
                return true;
            }

            @Override
            public String[] interactive(ClientSession session, String name, String instruction, String lang, String[] prompt, boolean[] echo) {
                throw new UnsupportedOperationException("Unexpected call");
            }

            @Override
            public String getUpdatedPassword(ClientSession session, String prompt, String lang) {
                assertEquals(getCurrentTestName(), prompt, "Mismatched prompt");
                assertEquals(CoreModuleProperties.WELCOME_BANNER_LANGUAGE.getRequiredDefault(), lang, "Mismatched language");
                assertEquals(1, updatesCount.incrementAndGet(), "Unexpected repeated call");
                return getCurrentTestName();
            }
        });
        AtomicInteger sentCount = new AtomicInteger(0);
        client.setUserAuthFactories(Collections.singletonList(new org.apache.sshd.client.auth.password.UserAuthPasswordFactory() {

            @Override
            public org.apache.sshd.client.auth.password.UserAuthPassword createUserAuth(ClientSession session) throws IOException {
                return new org.apache.sshd.client.auth.password.UserAuthPassword() {

                    @Override
                    protected IoWriteFuture sendPassword(Buffer buffer, ClientSession session, String oldPassword, String newPassword) throws Exception {
                        int count = sentCount.incrementAndGet();
                        // 1st one is the original one (which is denied by the server)
                        // 2nd one is the updated one retrieved from the user interaction
                        if (count == 2) {
                            return super.sendPassword(buffer, session, getClass().getName(), newPassword);
                        } else {
                            return super.sendPassword(buffer, session, oldPassword, newPassword);
                        }
                    }
                };
            }
        }));
