@MethodSource("portSpecifications")
@ParameterizedTest(name = "{0}")
public void forwardingWithConnectionClose(String portToForward) throws Exception {
    initPortForwardingWithOpenSshTest(portToForward);
    // Write the entrypoint file. From within the test container, the host running the container and our two servers
    // is accessible as "host.testcontainers.internal".
    File entryPoint = File.createTempFile("junit", null, tmp);
    String lines = //
    "#!/bin/sh\n" + //
    "\n" + //
    "chmod 0600 /root/.ssh/*\n" + "/usr/bin/ssh -o 'ExitOnForwardFailure yes' -o 'StrictHostKeyChecking off' -vvv -p " + //
    sshPort + " -x -N -T -R " + portToForward + ":host.testcontainers.internal:" + //
    gRpcPort + " bob@host.testcontainers.internal\n";
    Files.write(entryPoint.toPath(), lines.getBytes(StandardCharsets.US_ASCII));
    // Create the container
    @SuppressWarnings("resource")
    GenericContainer<?> sshdContainer = new GenericContainer<>(new ImageFromDockerfile().withDockerfileFromBuilder(builder -> //
    builder.from("alpine:3.16").run(// Installs OpenSSH 9.0
    "apk --update add openssh openssh-server").run(// Create the SSH config directory
    "mkdir -p /root/.ssh").entryPoint(//
    "/entrypoint.sh").//
    build())).withCopyFileToContainer(MountableFile.forClasspathResource(TEST_KEYS + "/user01_ed25519"), "/root/.ssh/id_ed25519").withCopyFileToContainer(MountableFile.forClasspathResource(TEST_KEYS + "/user01_ed25519.pub"), "/root/.ssh/id_ed25519.pub").// Spotbugs doesn't like 0777, so use hex
    withCopyFileToContainer(MountableFile.forHostPath(entryPoint.getPath(), 0x1ff), "/entrypoint.sh").withAccessToHost(//
    true).waitingFor(Wait.forLogMessage(".*forwarding_success.*\n", 1)).withLogConsumer(new Slf4jLogConsumer(LOG));
    try {
        Testcontainers.exposeHostPorts(sshPort, gRpcPort);
        sshdContainer.start();
        forwardingSetup.await();
        assertTrue(forwardedPort > 0, "Server should listen on port");
        LOG.info("sshd server listening for forwarding on port {}", forwardedPort);
        // Connect to the forwarded port. We should end up connecting to the gRPC server, which will balk
        // because it expects HTTP 2, and disconnect.
        List<String> content = new ArrayList<>();
        try (Socket socket = new Socket("127.0.0.1", forwardedPort)) {
            try (OutputStream out = socket.getOutputStream();
                InputStream in = socket.getInputStream()) {
                String command = //
                "GET / HTTP 1.1\r\n" + //
                "Connection: keep-alive\r\n" + //
                "Host: 127.0.0.1\r\n" + "\r\n";
                out.write(command.getBytes(StandardCharsets.US_ASCII));
                byte[] buf = new byte[1024];
                for (int n = 0; n >= 0; ) {
                    n = in.read(buf, 0, buf.length);
                    if (n > 0) {
                        String data = new String(buf, 0, n, StandardCharsets.ISO_8859_1);
                        content.add(data);
                    }
                }
            }
        }
        assertFalse(content.isEmpty(), "Expected data");
        String last = content.get(content.size() - 1);
        assertTrue(last.endsWith("HTTP/2 client preface string missing or corrupt. Hex dump for received bytes: 474554202f204854545020312e310d0a436f6e6e65637469"), "Unexpected data: " + last);
    } finally {
        sshdContainer.stop();
    }
}

