@Test
void connectorRace() throws Exception {
    CountDownLatch connectionMade = new CountDownLatch(1);
    CountDownLatch connectorClosing = new CountDownLatch(1);
    CountDownLatch futureTriggered = new CountDownLatch(1);
    CountDownLatch ioSessionClosed = new CountDownLatch(1);
    AtomicReference<IoSession> session = new AtomicReference<>();
    AtomicBoolean connectorIsClosing = new AtomicBoolean();
    AtomicBoolean sessionWaited = new AtomicBoolean();
    SshClient client = setupTestClient();
    IoServiceFactory serviceFactory = DefaultIoServiceFactoryFactory.getDefaultIoServiceFactoryFactoryInstance().create(client);
    IoConnector connector = serviceFactory.createConnector(new IoHandler() {

        @Override
        public void sessionCreated(org.apache.sshd.common.io.IoSession session) throws Exception {
            connectionMade.countDown();
            sessionWaited.set(connectorClosing.await(5, TimeUnit.SECONDS));
        }

        @Override
        public void sessionClosed(org.apache.sshd.common.io.IoSession session) throws Exception {
            ioSessionClosed.countDown();
        }

        @Override
        public void exceptionCaught(org.apache.sshd.common.io.IoSession session, Throwable cause) throws Exception {
            // Nothing
        }

        @Override
        public void messageReceived(org.apache.sshd.common.io.IoSession session, Readable message) throws Exception {
            // Nothing; we're not actually sending or receiving data.
        }
    });
    NioSocketAcceptor acceptor = startEchoServer();
    try {
        InetSocketAddress connectAddress = new InetSocketAddress(InetAddress.getByName(TEST_LOCALHOST), acceptor.getLocalAddress().getPort());
        IoConnectFuture future = connector.connect(connectAddress, null, null);
        connectionMade.await(5, TimeUnit.SECONDS);
        connector.close();
        connectorClosing.countDown();
        future.addListener(new SshFutureListener<IoConnectFuture>() {

            @Override
            public void operationComplete(IoConnectFuture future) {
                session.set(future.getSession());
                connectorIsClosing.set(!connector.isOpen());
                futureTriggered.countDown();
            }
        });
        assertTrue(futureTriggered.await(5, TimeUnit.SECONDS));
        Throwable error = future.getException();
        if (error != null) {
            LOG.info("{}: Connect future was terminated exceptionally: {} ", getCurrentTestName(), error);
            error.printStackTrace();
        } else if (future.isCanceled()) {
            LOG.info("{}: Connect future was canceled", getCurrentTestName());
        }
        assertEquals(0, connectionMade.getCount());
        assertTrue(sessionWaited.get());
        assertNull(session.get());
        assertTrue(connectorIsClosing.get());
        // Since sessionCreated() was called we also expect sessionClosed() to get called eventually.
        assertTrue(ioSessionClosed.await(5, TimeUnit.SECONDS));
    } finally {
        acceptor.dispose(false);
    }
}

// see SSHD-554, SSHD-722
@Test
void setSocketOptions() throws Exception {
    try (SshServer sshd = setupTestServer()) {
        Map<Property<?>, Object> expectedOptions = new LinkedHashMap<>();
        expectedOptions.put(CoreModuleProperties.SOCKET_KEEPALIVE, true);
        expectedOptions.put(CoreModuleProperties.SOCKET_LINGER, 5);
        expectedOptions.put(CoreModuleProperties.SOCKET_RCVBUF, 1024);
        expectedOptions.put(CoreModuleProperties.SOCKET_REUSEADDR, true);
        expectedOptions.put(CoreModuleProperties.SOCKET_SNDBUF, 1024);
        expectedOptions.put(CoreModuleProperties.TCP_NODELAY, true);
        for (Map.Entry<Property<?>, ?> oe : expectedOptions.entrySet()) {
            PropertyResolverUtils.updateProperty(sshd, oe.getKey().getName(), oe.getValue());
        }
        Semaphore sigSem = new Semaphore(0, true);
        Map<SocketOption<?>, Map.Entry<?, ?>> actualOptionValues = new HashMap<>(expectedOptions.size());
        sshd.setSessionFactory(new SessionFactory(sshd) {

            @Override
            protected ServerSessionImpl doCreateSession(IoSession ioSession) throws Exception {
                validateSocketOptions(ioSession);
                sigSem.release();
                return super.doCreateSession(ioSession);
            }

            private void validateSocketOptions(IoSession ioSession) throws Exception {
                if (!(ioSession instanceof Nio2Session)) {
                    return;
                }
                AsynchronousSocketChannel socket = ((Nio2Session) ioSession).getSocket();
                Collection<? extends SocketOption<?>> supported = socket.supportedOptions();
                if (GenericUtils.isEmpty(supported)) {
                    return;
                }
                for (Map.Entry<Property<?>, ?> oe : expectedOptions.entrySet()) {
                    Property<?> prop = oe.getKey();
                    Object expValue = oe.getValue();
                    Map.Entry<SocketOption<?>, ?> optionEntry = Nio2Service.CONFIGURABLE_OPTIONS.get(prop);
                    SocketOption<?> option = optionEntry.getKey();
                    if (!supported.contains(option)) {
                        continue;
                    }
                    Object actValue = socket.getOption(option);
                    actualOptionValues.put(option, new SimpleImmutableEntry<>(expValue, actValue));
                }
            }
        });
        sshd.start();
        int port = sshd.getPort();
        long startTime = System.nanoTime();
        try (Socket s = new Socket(TEST_LOCALHOST, port)) {
            long endTime = System.nanoTime();
            long duration = endTime - startTime;
            assertTrue(duration <= TimeUnit.SECONDS.toNanos(15L), "Connect duration is too high: " + duration);
            assertTrue(sigSem.tryAcquire(15L, TimeUnit.SECONDS), "Validation not completed on time");
        } finally {
            sshd.stop();
        }
        // NOTE: we do not fail the test since some O/S implementations treat the value as a recommendation - i.e.,
        // they might ignore it
        for (Map.Entry<SocketOption<?>, ? extends Map.Entry<?, ?>> mme : actualOptionValues.entrySet()) {
            SocketOption<?> option = mme.getKey();
            Map.Entry<?, ?> vp = mme.getValue();
            Object expValue = vp.getKey();
            Object actValue = vp.getValue();
            Appendable output = Objects.equals(expValue, actValue) ? System.out : System.err;
            output.append('\t').append(option.name()).append(": expected=").append(Objects.toString(expValue)).append(", actual=").append(Objects.toString(actValue)).append(System.lineSeparator());
            if (output instanceof Flushable) {
                ((Flushable) output).flush();
            }
        }
    }
}

@Test
void stripLeadingZeroes() {
    byte[] data = { 3, 7, 7, 3, 4, 7 };
    for (int index = 1; index <= data.length; index++) {
        assertSame(data, AbstractDH.stripLeadingZeroes(data), "Unexpected sub-array generation for " + Arrays.toString(data));
        if (index < data.length) {
            data[index] = 0;
        }
    }
    Arrays.fill(data, (byte) 0);
    try {
        byte[] stripped = AbstractDH.stripLeadingZeroes(data);
        fail("Unexpected success for all zeroes data: " + Arrays.toString(stripped));
    } catch (IllegalArgumentException expected) {
        // ignored
    }
    for (int index = data.length - 1; index > 0; index--) {
        data[index] = (byte) index;
        byte[] stripped = AbstractDH.stripLeadingZeroes(data);
        String ds = Arrays.toString(data);
        String ss = Arrays.toString(stripped);
        assertEquals(data.length - index, stripped.length, "Mismatched stripped (" + ss + ") length for " + ds);
        for (int i = index, j = 0; j < stripped.length; i++, j++) {
            if (data[i] != stripped[j]) {
                fail("Mismatched values at stripped index = " + j + ": data=" + ds + ", stripped=" + ss);
            }
        }
    }
}

