                        try {
                            testReservedSessionMessagesHandler(session, handler);
                            outputDebugMessage("Release test signal for %s", session);
                            signal.release();
                        } catch (Throwable t) {
                            outputDebugMessage("Failed (%s) to run test: %s", t.getClass().getSimpleName(), t.getMessage());
