@Test
void reExchangeFromSshdClient() throws Exception {
    setUp(0L, Duration.ZERO, 0L);
    try (SshClient client = setupTestClient()) {
        client.start();
        try (ClientSession session = client.connect(getCurrentTestName(), TEST_LOCALHOST, port).verify(CONNECT_TIMEOUT).getSession()) {
            session.addPasswordIdentity(getCurrentTestName());
            session.auth().verify(AUTH_TIMEOUT);
            final Semaphore pipedCount = new Semaphore(0, true);
            try (ChannelShell channel = session.createShellChannel();
                ByteArrayOutputStream sent = new ByteArrayOutputStream();
                PipedOutputStream pipedIn = new PipedOutputStream();
                InputStream inPipe = new PipedInputStream(pipedIn);
                OutputStream teeOut = new TeeOutputStream(sent, pipedIn);
                ByteArrayOutputStream out = new ByteArrayOutputStream() {

                    private long writeCount;

                    @Override
                    public synchronized void write(int b) {
                        super.write(b);
                        updateWriteCount(1L);
                        pipedCount.release(1);
                    }

                    @Override
                    public synchronized void write(byte[] b, int off, int len) {
                        super.write(b, off, len);
                        updateWriteCount(len);
                        pipedCount.release(len);
                    }

                    private void updateWriteCount(long delta) {
                        writeCount += delta;
                        outputDebugMessage("OUT write count=%d", writeCount);
                    }
                };
                ByteArrayOutputStream err = new ByteArrayOutputStream()) {
                channel.setIn(inPipe);
                channel.setOut(out);
                channel.setErr(err);
                channel.open();
                teeOut.write("this is my command\n".getBytes(StandardCharsets.UTF_8));
                teeOut.flush();
                StringBuilder sb = new StringBuilder(Byte.MAX_VALUE);
                for (int i = 0; i < 10; i++) {
                    sb.append("0123456789");
                }
                sb.append('\n');
                byte[] data = sb.toString().getBytes(StandardCharsets.UTF_8);
                for (int i = 1; i <= 10; i++) {
                    teeOut.write(data);
                    teeOut.flush();
                    KeyExchangeFuture kexFuture = session.reExchangeKeys();
                    assertTrue(kexFuture.await(DEFAULT_TIMEOUT), "Failed to complete KEX on time at iteration " + i);
                    assertNull(kexFuture.getException(), "KEX exception signalled at iteration " + i);
                }
                teeOut.write("exit\n".getBytes(StandardCharsets.UTF_8));
                teeOut.flush();
                Collection<ClientChannelEvent> result = channel.waitFor(EnumSet.of(ClientChannelEvent.CLOSED), DEFAULT_TIMEOUT);
                assertFalse(result.contains(ClientChannelEvent.TIMEOUT), "Timeout while waiting for channel closure");
                byte[] expected = sent.toByteArray();
