@Test
void socksProxy() throws Exception {
    final AtomicReference<SshdSocketAddress> localAddressHolder = new AtomicReference<>();
    final AtomicReference<SshdSocketAddress> boundAddressHolder = new AtomicReference<>();
    final AtomicInteger tearDownSignal = new AtomicInteger(0);
    @SuppressWarnings("checkstyle:anoninnerlength")
    PortForwardingEventListener listener = new PortForwardingEventListener() {

        @Override
        public void tornDownExplicitTunnel(org.apache.sshd.common.session.Session session, SshdSocketAddress address, boolean localForwarding, SshdSocketAddress remoteAddress, Throwable reason) throws IOException {
            throw new UnsupportedOperationException("Unexpected explicit tunnel torn down indication: session=" + session + ", address=" + address);
        }

        @Override
        public void tornDownDynamicTunnel(org.apache.sshd.common.session.Session session, SshdSocketAddress address, Throwable reason) throws IOException {
            assertNotNull(localAddressHolder.get(), "Establishment (local) indication not invoked for address=" + address);
            assertNotNull(boundAddressHolder.get(), "Establishment (bound) indication not invoked for address=" + address);
            assertEquals(1, tearDownSignal.get(), "No tear down indication");
        }

        @Override
        public void tearingDownExplicitTunnel(org.apache.sshd.common.session.Session session, SshdSocketAddress address, boolean localForwarding, SshdSocketAddress remoteAddress) throws IOException {
            throw new UnsupportedOperationException("Unexpected explicit tunnel tear down indication: session=" + session + ", address=" + address);
        }

        @Override
        public void tearingDownDynamicTunnel(org.apache.sshd.common.session.Session session, SshdSocketAddress address) throws IOException {
            assertNotNull(localAddressHolder.get(), "Establishment (local) indication not invoked for address=" + address);
            assertNotNull(boundAddressHolder.get(), "Establishment (bound) indication not invoked for address=" + address);
            assertEquals(1, tearDownSignal.incrementAndGet(), "Multiple tearing down indications");
        }

        @Override
        public void establishingExplicitTunnel(org.apache.sshd.common.session.Session session, SshdSocketAddress local, SshdSocketAddress remote, boolean localForwarding) throws IOException {
            throw new UnsupportedOperationException("Unexpected explicit tunnel establishment indication: session=" + session + ", address=" + local);
        }

        @Override
        public void establishingDynamicTunnel(org.apache.sshd.common.session.Session session, SshdSocketAddress local) throws IOException {
            assertNull(localAddressHolder.getAndSet(local), "Multiple calls to establishment indicator");
        }

        @Override
        public void establishedExplicitTunnel(org.apache.sshd.common.session.Session session, SshdSocketAddress local, SshdSocketAddress remote, boolean localForwarding, SshdSocketAddress boundAddress, Throwable reason) throws IOException {
            throw new UnsupportedOperationException("Unexpected explicit tunnel established indication: session=" + session + ", address=" + boundAddress);
        }

        @Override
        public void establishedDynamicTunnel(org.apache.sshd.common.session.Session session, SshdSocketAddress local, SshdSocketAddress boundAddress, Throwable reason) throws IOException {
            assertSame(local, localAddressHolder.get(), "Establishment indication not invoked");
            assertNull(boundAddressHolder.getAndSet(boundAddress), "Multiple calls to establishment indicator");
        }

        @Override
        public String toString() {
            return getCurrentTestName();
        }
    };
    try (ClientSession session = createNativeSession(listener)) {
        String expected = getCurrentTestName();
        byte[] bytes = expected.getBytes(StandardCharsets.UTF_8);
        byte[] buf = new byte[bytes.length + Long.SIZE];
        SshdSocketAddress dynamic;
        try (DynamicPortForwardingTracker tracker = session.createDynamicPortForwardingTracker(new SshdSocketAddress(TEST_LOCALHOST, 0))) {
            dynamic = tracker.getBoundAddress();
            assertTrue(tracker.isOpen(), "Tracker not marked as open");
            for (int i = 0; i < 10; i++) {
                try (Socket s = new Socket(new Proxy(Proxy.Type.SOCKS, new InetSocketAddress(TEST_LOCALHOST, dynamic.getPort())))) {
                    s.connect(new InetSocketAddress(TEST_LOCALHOST, echoPort));
                    s.setSoTimeout((int) TimeUnit.SECONDS.toMillis(10L));
                    try (OutputStream sockOut = s.getOutputStream();
                        InputStream sockIn = s.getInputStream()) {
                        sockOut.write(bytes);
                        sockOut.flush();
                        int l = sockIn.read(buf);
                        assertEquals(expected, new String(buf, 0, l, StandardCharsets.UTF_8), "Mismatched data at iteration " + i);
                    }
                }
            }
            tracker.close();
            assertFalse(tracker.isOpen(), "Tracker not marked as closed");
        } finally {
            client.removePortForwardingEventListener(listener);
        }
        assertNotNull(localAddressHolder.getAndSet(null), "Local tunnel address not indicated");
        assertNotNull(boundAddressHolder.getAndSet(null), "Bound tunnel address not indicated");
        try {
            try (Socket s = new Socket(new Proxy(Proxy.Type.SOCKS, new InetSocketAddress(TEST_LOCALHOST, dynamic.getPort())))) {
                s.connect(new InetSocketAddress(TEST_LOCALHOST, echoPort));
                s.setSoTimeout((int) TimeUnit.SECONDS.toMillis(11L));
                s.getOutputStream().write(bytes);
                fail("Unexpected success to write proxy data");
            }
        } catch (IOException e) {
            // expected
        }
    }
}

