    List<Path> actual = new ArrayList<>();
    try (FileSystem fs = FileSystems.newFileSystem(createDefaultFileSystemURI(), Collections.emptyMap())) {
        DirectoryStream.Filter<Path> filter = p -> {
            if (Files.isDirectory(p)) {
                return true;
