@Test
void sftpVersionSelector() throws Exception {
    AtomicInteger selected = new AtomicInteger(-1);
    SftpVersionSelector selector = (session, initial, current, available) -> {
        int value = initial ? current : GenericUtils.stream(available).mapToInt(Integer::intValue).filter(v -> v != current).max().orElseGet(() -> current);
        selected.set(value);
        return value;
    };
    try (ClientSession session = createAuthenticatedClientSession();
        FileSystem fs = createSftpFileSystem(session, selector)) {
